files.content:
:root{--ink:#16221d;--muted:#58655d;--paper:#f4f1e8;--white:#fffefa;--green:#34664b;--line:#d8dfd2;--rust:#8b3725;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;--sans:Arial,Helvetica,sans-serif}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 var(--sans)}
a{color:var(--green);text-underline-offset:3px}
button,input{font:inherit}
h1,h2,h3,h4,p{margin-top:0}
h1{font-size:clamp(36px,6vw,66px);line-height:1.06;letter-spacing:-.055em;margin:16px 0 22px}
h1 em{font-family:Georgia,serif;font-weight:400;color:var(--green)}
h2{font-size:23px;letter-spacing:-.025em;margin-bottom:10px}
h3{font-size:21px;letter-spacing:-.025em}
h4{font-size:18px;line-height:1.35;margin:0}
.topbar,footer{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:19px clamp(20px,6vw,90px);border-bottom:1px solid var(--line)}
.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--ink);font-weight:700;letter-spacing:-.04em}
.brand-mark{display:grid;place-items:center;background:var(--green);color:white;width:30px;height:30px;border-radius:50%;font:20px Georgia,serif}
.fixture-label,.eyebrow{font:11px var(--mono);letter-spacing:.09em;color:var(--green)}
main{max-width:1100px;margin:auto;padding:56px clamp(20px,5vw,60px) 60px}
.intro{max-width:700px}
.lede{max-width:600px;font-size:18px;color:var(--muted);margin-bottom:32px}
.file-panel{background:var(--white);border:1px solid var(--line);padding:24px 28px;margin-bottom:36px}
.file-panel>p{font-size:13px;color:var(--muted)}
.file-controls{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin:20px 0 15px}
input[type=file]{max-width:100%;width:480px;font-size:14px;color:var(--muted)}
input[type=file]::file-selector-button{background:var(--ink);color:white;border:1px solid var(--ink);border-radius:4px;padding:13px 17px;margin-right:14px;font-weight:600;cursor:pointer}
button{min-height:45px;border:1px solid #b0bcae;border-radius:4px;background:transparent;color:var(--ink);padding:10px 16px;font-size:14px;cursor:pointer}
button:disabled{opacity:.5;cursor:default}
.file-panel .privacy{margin-bottom:18px}
.file-panel .load-status{padding-top:16px;border-top:1px solid var(--line);color:var(--ink);overflow-wrap:anywhere}
.file-panel .load-error{border-left:3px solid var(--rust);background:#fff0e9;padding:12px 14px;color:var(--rust);overflow-wrap:anywhere}
.jump-link{font-size:14px;display:inline-block;padding:6px 0}
.record-heading{margin-bottom:22px}
.record-heading h2{font-size:clamp(25px,4vw,35px);line-height:1.2}
.record-filename{font:12px/1.6 var(--mono);color:var(--muted);overflow-wrap:anywhere;margin-bottom:10px}
.record-notice{display:inline-block;background:#e5eddc;border:1px solid #c0d0b5;padding:6px 10px;color:#284934;font-size:12px;margin:0}
.record-totals{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);gap:1px;background:var(--line);margin:0 0 34px}
.record-totals>div{padding:17px 19px;background:var(--white)}
dt{font:11px/1.5 var(--mono);color:var(--muted)}
dd{margin:6px 0 0;overflow-wrap:anywhere}
.record-totals dd{font-size:23px;font-weight:700;letter-spacing:-.04em}
.section-title{margin-bottom:17px}
.saved-checkpoint{padding:23px 26px;background:var(--white);border:1px solid var(--line);margin-bottom:16px}
.checkpoint-heading{display:flex;align-items:baseline;justify-content:space-between;gap:14px}
.checkpoint-amount{font-size:15px;white-space:nowrap}
.approval-state,.unapproved-state{font:12px/1.5 var(--mono);margin:12px 0 20px}
.approval-state{color:var(--green)}
.unapproved-state{color:var(--muted)}
.field-label{font:11px var(--mono);letter-spacing:.06em;color:var(--muted);margin-bottom:8px}
.accepted-evidence{font:15px/1.65 var(--sans);margin:0 0 20px;padding:15px 18px;background:#f3f5ed;border-left:3px solid var(--green);white-space:pre-wrap;overflow-wrap:anywhere}
.empty-evidence{color:var(--muted);font-size:14px}
.saved-capture{border-top:1px solid var(--line);padding-top:14px}
.capture-state{font-size:14px}
.saved-capture p{font-size:13px;color:var(--muted);margin:4px 0 0}
.saved-capture[data-capture-state=unknown] .capture-state{color:var(--rust)}
.record-identities{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin:17px 0 0}
.record-identities dd{font:12px/1.5 var(--mono)}
.record-history{margin-top:34px}
.history-help,.record-footnote{font-size:13px;color:var(--muted)}
.event-list{list-style:none;margin:0;padding:0;border:1px solid var(--line);background:var(--white)}
.event-list>li+li{border-top:1px solid var(--line)}
.saved-event summary{display:flex;align-items:center;gap:15px;cursor:pointer;padding:15px 20px;list-style:none}
.saved-event summary::-webkit-details-marker{display:none}
.saved-event summary:after{content:"+";margin-left:auto;font-size:20px;flex-shrink:0;color:var(--green)}
.saved-event[open] summary:after{content:"−"}
.event-sequence{font:12px var(--mono);color:var(--green)}
.event-description{min-width:0}
.event-description strong,.event-description>span{display:block}
.event-description strong{font-size:14px;font-weight:600}
.event-description>span{font-size:12px;color:var(--muted)}
.event-json{margin:0 20px 20px;padding:15px;background:#f3f5ed;font:12px/1.6 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere}
.record-footnote{margin:24px 0 0}
footer{border:0;border-top:1px solid var(--line);font-size:12px;color:var(--muted);flex-wrap:wrap}
:focus-visible{outline:3px solid #659342;outline-offset:4px}
.skip-link{position:absolute;left:-9999px;top:12px;padding:10px;background:var(--ink);color:white;z-index:2}
.skip-link:focus{left:20px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:650px){.record-totals{grid-template-columns:repeat(2,minmax(0,1fr))}.record-identities{grid-template-columns:1fr}.fixture-label{font-size:9px}.file-panel,.saved-checkpoint{padding:20px}.record-totals>div{padding:15px}.record-totals dd{font-size:21px}.checkpoint-heading{align-items:flex-start}.file-controls{gap:14px}.saved-event summary{padding:14px}.event-json{margin:0 14px 14px}main{padding-top:36px}.topbar{padding:16px 20px}}
@media print{.file-panel,.intro,.skip-link,footer{display:none}.topbar{padding:10px 0}main{max-width:none;padding:20px 0}.saved-checkpoint{break-inside:avoid}.record-history{break-before:auto}body{background:white}}

.record-review-download{margin-top:16px}
.record-review-download-status{font-size:14px;overflow-wrap:anywhere;white-space:pre-wrap}
.record-review-download-status:empty{display:none}

.record-event-filter{margin:18px 0;padding:18px;background:var(--white);border:1px solid var(--line)}
.record-event-filter-controls{display:flex;flex-wrap:wrap;align-items:end;gap:14px}
.record-event-filter label{display:grid;gap:6px;font-size:13px;flex:1 1 220px;min-width:0}
.record-event-filter select{font:inherit;color:var(--ink);background:var(--white);border:1px solid #b0bcae;border-radius:4px;min-height:45px;padding:10px;max-width:100%;width:100%}
.record-event-filter p{font-size:13px;color:var(--muted);margin:14px 0 0;overflow-wrap:anywhere}
.record-event-filter .record-event-empty{color:var(--ink)}
@media print{.record-event-filter-controls{display:none}.record-event-filter{padding:0;border:0}}

import { createRecordEventFilter } from './record-event-filter.mjs';
import { createRecordReviewDownload } from './record-review-download.mjs';
import { FixtureRecordError, MAX_RECORD_BYTES, readFixtureRecord } from './record-reader.mjs';

const input = document.getElementById('record-file');
const clear = document.getElementById('clear-record');
const status = document.getElementById('record-status');
const error = document.getElementById('record-error');
const display = document.getElementById('record-display');
const jump = document.getElementById('jump-to-record');
const money = cents => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
const stateLabels = {
  not_started: 'Not started', ready: 'Order ready', pending: 'Capture pending',
  unknown: 'Capture unknown', captured: 'Capture recorded',
};
const eventLabels = {
  'checkpoint.approved': 'Human approval recorded',
  'paypal.order.created': 'Fixture order created',
  'paypal.capture.requested': 'Capture requested',
  'paypal.capture.response_lost': 'Capture response lost',
  'paypal.webhook.received': 'Webhook received',
  'paypal.capture.reconciled': 'Capture reconciled',
};
let request = 0;
let opened = false;

function element(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function fact(list, label, value) {
  const pair = element('div');
  pair.append(element('dt', '', label), element('dd', '', value));
  list.append(pair);
}

function captureNote(checkpoint) {
  switch (checkpoint.capture.status) {
    case 'captured': return 'This capture contributes ' + money(checkpoint.capture.counted) + ' to the recorded fixture total.';
    case 'unknown': return 'The saved history ends before reconciliation. No captured amount is counted for this checkpoint.';
    case 'pending': return 'A capture request is recorded, but the saved history has no final outcome.';
    case 'ready': return 'An approved fixture order is recorded. No captured amount is counted.';
    default: return 'No fixture capture is recorded.';
  }
}

function renderRecord(record, filename) {
  const fragment = document.createDocumentFragment();
  const heading = element('header', 'record-heading');
  heading.append(element('p', 'eyebrow', 'OPEN RECORD'));
  const title = element('h2', '', record.fixture.label);
  title.id = 'record-title';
  title.tabIndex = -1;
  heading.append(title, element('p', 'record-filename', filename));
  heading.append(element('p', 'record-notice', 'Synthetic fixture · Not payment evidence'));
  heading.append(createRecordReviewDownload(record, filename));
  fragment.append(heading);

  const summary = element('dl', 'record-totals');
  summary.setAttribute('aria-label', 'Recorded fixture totals');
  fact(summary, 'Project cap', money(record.summary.total));
  fact(summary, 'Approvals recorded', record.summary.approved + ' / ' + record.checkpoints.length);
  fact(summary, 'Captures recorded', money(record.summary.captured));
  fact(summary, 'Remaining in fixture', money(record.summary.remaining));
  fragment.append(summary);

  const checkpoints = element('section', 'record-checkpoints');
  const checkpointTitle = element('h3', 'section-title', 'Accepted evidence and outcomes');
  checkpointTitle.id = 'saved-checkpoints-title';
  checkpoints.setAttribute('aria-labelledby', checkpointTitle.id);
  checkpoints.append(checkpointTitle);
  for (const checkpoint of record.checkpoints) {
    const card = element('article', 'saved-checkpoint');
    card.dataset.checkpointId = checkpoint.id;
    const header = element('div', 'checkpoint-heading');
    header.append(element('h4', '', checkpoint.title), element('strong', 'checkpoint-amount', money(checkpoint.amount)));
    card.append(header);
    if (checkpoint.approval) {
      card.append(element('p', 'approval-state', 'Approval recorded · Event ' + checkpoint.approval.eventSequence + ' · ' + checkpoint.approval.approver));
      card.append(element('p', 'field-label', 'EXACT ACCEPTED EVIDENCE'));
      card.append(element('pre', 'accepted-evidence', checkpoint.approval.acceptedEvidence));
    } else {
      card.append(element('p', 'unapproved-state', 'No approval recorded'));
      card.append(element('p', 'empty-evidence', 'This file contains no accepted evidence for this checkpoint.'));
    }
    const capture = element('div', 'saved-capture');
    capture.dataset.captureState = checkpoint.capture.status;
    capture.append(element('strong', 'capture-state', stateLabels[checkpoint.capture.status]));
    capture.append(element('p', '', captureNote(checkpoint)));
    card.append(capture);
    const identities = element('dl', 'record-identities');
    fact(identities, 'Order', checkpoint.capture.orderId ?? 'None recorded');
    fact(identities, 'Confirmed capture', checkpoint.capture.captureId ?? 'None recorded');
    fact(identities, 'Counted amount', money(checkpoint.capture.counted));
    card.append(identities);
    checkpoints.append(card);
  }
  fragment.append(checkpoints);

  const history = element('section', 'record-history');
  const historyTitle = element('h3', 'section-title', 'Recorded event history');
  historyTitle.id = 'saved-history-title';
  history.setAttribute('aria-labelledby', historyTitle.id);
  history.append(historyTitle);
  history.append(element('p', 'history-help', record.events.length + ' events. Open an event to read its exact saved fields. T+ values are sequence markers, not clock times.'));
  if (!record.events.length) history.append(element('p', '', 'This record contains no events.'));
  const list = element('ol', 'event-list');
  for (const event of record.events) {
    const row = element('li');
    const detail = element('details', 'saved-event');
    const summary = element('summary');
    const checkpoint = record.checkpoints.find(item => item.id === event.checkpointId);
    const label = event.type === 'paypal.webhook.received' && event.duplicate ? 'Duplicate webhook recorded' : eventLabels[event.type];
    summary.append(element('span', 'event-sequence', String(event.seq).padStart(2, '0')));
    const description = element('span', 'event-description');
    description.append(element('strong', '', label), element('span', '', checkpoint.title));
    summary.append(description);
    detail.append(summary, element('pre', 'event-json', JSON.stringify(event, null, 2)));
    row.append(detail);
    list.append(row);
  }
  history.append(createRecordEventFilter(record, list, eventLabels), list);
  fragment.append(history);
  fragment.append(element('p', 'record-footnote', 'The file is unsigned. Consistent fields do not establish who wrote it or prove a real approval or transaction.'));
  return fragment;
}

input.addEventListener('change', async () => {
  const file = input.files?.[0];
  // Clearing the picker permits choosing the same file again after a refusal.
  input.value = '';
  if (!file) return;
  const current = ++request;
  clear.disabled = false;
  error.hidden = true;
  error.textContent = '';
  status.textContent = 'Opening ' + file.name + '…' + (opened ? ' Your current record remains below.' : '');
  try {
    if (file.size > MAX_RECORD_BYTES) {
      throw new FixtureRecordError('size', 'This file exceeds the 1 MiB limit. Choose a smaller fixture-record export.');
    }
    const bytes = await file.arrayBuffer();
    if (current !== request) return;
    let text;
    try { text = new TextDecoder('utf-8', { fatal: true }).decode(bytes); }
    catch { throw new FixtureRecordError('encoding', 'This file is not valid UTF-8. Choose the original JSON download.'); }
    const record = readFixtureRecord(text);
    // Prepare all content before replacing a previously accepted display.
    const content = renderRecord(record, file.name);
    if (current !== request) return;
    display.replaceChildren(content);
    display.hidden = false;
    jump.hidden = false;
    opened = true;
    status.textContent = 'Opened ' + file.name + '. ' + record.events.length + ' events; ' + record.summary.approved + ' approvals recorded. The saved fields match the event history.';
  } catch (failure) {
    if (current !== request) return;
    error.textContent = (failure instanceof FixtureRecordError ? failure.message : 'This file could not be read. Choose it again or select another saved record.')
      + (opened ? ' Your previously opened record is unchanged.' : ' No record has been opened.');
    error.hidden = false;
    status.textContent = opened ? 'The previous record remains open.' : 'No file open.';
    clear.disabled = !opened;
  }
});

clear.addEventListener('click', () => {
  ++request;
  opened = false;
  input.value = '';
  display.replaceChildren();
  display.hidden = true;
  jump.hidden = true;
  error.hidden = true;
  error.textContent = '';
  status.textContent = 'View cleared. Choose a saved fixture record to inspect.';
  clear.disabled = true;
  input.focus();
});

import { SPEC_VERSION } from './ledger.mjs';
import { createFixtureRecord } from './fixture-record.mjs';

// The ledger owns lifecycle and identity rules. This reader only admits the
// saved-file format and checks the redundant facts against that same ledger.
export const MAX_RECORD_BYTES = 1024 * 1024;
export const MAX_RECORD_EVENTS = 512;

export class FixtureRecordError extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'FixtureRecordError';
    this.code = code;
  }
}

const fields = {
  'checkpoint.approved': ['checkpointId', 'approver', 'acceptedEvidence'],
  'paypal.order.created': ['checkpointId', 'orderId', 'amount', 'currency', 'environment'],
  'paypal.capture.requested': ['checkpointId', 'orderId', 'environment'],
  'paypal.capture.response_lost': ['checkpointId', 'orderId', 'outcome'],
  'paypal.webhook.received': ['checkpointId', 'eventId', 'captureId', 'duplicate', 'amount', 'currency'],
  'paypal.capture.reconciled': ['checkpointId', 'captureId', 'outcome', 'source'],
};

function refuse(code, message) { throw new FixtureRecordError(code, message); }
function object(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }

function requireKeys(value, expected, label) {
  if (!object(value) || Object.keys(value).length !== expected.length
    || expected.some(key => !Object.hasOwn(value, key))) {
    refuse('format', label + ' has missing or unsupported fields. Choose an original fixture-record export.');
  }
}

// Iterative comparison also refuses extra fields. JSON key order is irrelevant;
// array order, string contents, amounts, nulls and types must match exactly.
function requireMatchingFacts(actual, expected) {
  const pending = [[actual, expected, 'record']];
  while (pending.length) {
    const [value, reference, path] = pending.pop();
    if (reference === null || typeof reference !== 'object') {
      if (value !== reference) refuse('inconsistent', 'The saved ' + path + ' does not match the event history.');
      continue;
    }
    if (Array.isArray(reference)) {
      if (!Array.isArray(value) || value.length !== reference.length) {
        refuse('inconsistent', 'The saved ' + path + ' does not match the event history.');
      }
      reference.forEach((item, index) => pending.push([value[index], item, path + '[' + index + ']']));
    } else {
      requireKeys(value, Object.keys(reference), 'The saved ' + path);
      for (const key of Object.keys(reference)) pending.push([value[key], reference[key], path + '.' + key]);
    }
  }
}

function freezeRecord(record) {
  const pending = [record];
  while (pending.length) {
    const value = pending.pop();
    if (value !== null && typeof value === 'object' && !Object.isFrozen(value)) {
      pending.push(...Object.values(value));
      Object.freeze(value);
    }
  }
  return record;
}

export function readFixtureRecord(text) {
  if (typeof text !== 'string') refuse('format', 'Choose a JSON fixture-record file.');
  if (text.length > MAX_RECORD_BYTES || new TextEncoder().encode(text).byteLength > MAX_RECORD_BYTES) {
    refuse('size', 'This file exceeds the 1 MiB limit. Choose a smaller fixture-record export.');
  }
  let saved;
  try { saved = JSON.parse(text); }
  catch { refuse('syntax', 'This file is not complete JSON. Choose a saved ScopeSignal fixture record.'); }

  if (!object(saved) || saved.schema !== 'scopesignal.fixture-record') {
    refuse('format', 'This is not a ScopeSignal fixture record.');
  }
  if (saved.version !== 1 || saved.ledgerSpecVersion !== SPEC_VERSION) {
    refuse('version', 'This record version is not supported. Open a version 1 fixture-record export.');
  }
  if (saved.fixtureOnly !== true || saved.paymentEvidence !== false) {
    refuse('format', 'This reader only supports synthetic fixture records, never payment evidence.');
  }
  if (!Array.isArray(saved.events) || saved.events.length > MAX_RECORD_EVENTS) {
    refuse('events', 'Choose a fixture record with no more than 512 events.');
  }
  saved.events.forEach((event, index) => {
    const label = 'Event ' + (index + 1);
    if (!object(event) || typeof event.type !== 'string' || !Object.hasOwn(fields, event.type)) {
      refuse('history', label + ' is not a supported fixture event.');
    }
    const payloadFields = fields[event.type];
    requireKeys(event, ['seq', 'type', 'at', ...payloadFields], label);
    if (event.seq !== index + 1 || event.at !== 'T+' + String(index + 1).padStart(3, '0')) {
      refuse('history', label + ' has inconsistent sequence metadata.');
    }
    for (const key of payloadFields) {
      const expectedType = key === 'amount' ? 'number' : key === 'duplicate' ? 'boolean' : 'string';
      if (typeof event[key] !== expectedType) refuse('history', label + ' has an invalid ' + key + ' field.');
    }
  });

  let record;
  try { record = createFixtureRecord(saved.events); }
  catch {
    refuse('history', 'The event history violates the fixture ledger rules. Choose an unedited export.');
  }
  requireMatchingFacts(saved, record);
  return freezeRecord(record);
}

import { createRecordReviewDocument, RECORD_REVIEW_FILENAME } from './record-review-export.mjs';

// Each control belongs to exactly one admitted rendered record. Opening or
// clearing a record removes it with that record; pending reads cannot retarget it.
export function createRecordReviewDownload(record, filename) {
  const group = document.createElement('div');
  group.className = 'record-review-download';
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'Download record review';
  const status = document.createElement('p');
  status.className = 'record-review-download-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  status.setAttribute('aria-atomic', 'true');
  group.append(button, status);
  button.addEventListener('click', () => {
    let url;
    let link;
    status.textContent = '';
    try {
      const html = createRecordReviewDocument(record, filename);
      url = URL.createObjectURL(new Blob([html], { type: 'text/html;charset=utf-8' }));
      link = document.createElement('a');
      link.href = url;
      link.download = RECORD_REVIEW_FILENAME;
      link.hidden = true;
      document.body.append(link);
      link.click();
      status.textContent = 'Record review download prepared. Keep the original JSON to reopen the interactive viewer.';
    } catch (failure) {
      status.textContent = 'The record review could not be prepared. Your opened record and original JSON are unchanged. '
        + (failure instanceof Error ? failure.message : 'Try again.');
    } finally {
      link?.remove();
      if (url) setTimeout(() => URL.revokeObjectURL(url), 0);
    }
  });
  return group;
}

export const SPEC_VERSION = 1;

export const FIXTURE = Object.freeze({
  id: 'fixture-signal-studio',
  label: 'Northstar onboarding refresh',
  currency: 'USD',
  amount: 120000,
  buyer: 'Northstar Studio (fictional fixture)',
  seller: 'Signal Works (fictional fixture)',
  brief: 'Refresh the onboarding flow for a small-business invoicing app. Deliver an accessible first-run checklist, responsive billing setup, and a documented handoff.',
  checkpoints: [
    { id: 'journey', title: 'First-run checklist', amount: 40000, evidence: 'A screen recording shows the checklist completion path and reset behavior.' },
    { id: 'accessibility', title: 'Accessible billing setup', amount: 40000, evidence: 'Keyboard-only walkthrough and automated accessibility report for the billing setup.' },
    { id: 'handoff', title: 'Responsive handoff', amount: 40000, evidence: 'Desktop and mobile handoff files plus implementation notes.' }
  ]
});

const EVENT_FIELDS = Object.freeze({
  'checkpoint.approved': ['checkpointId', 'approver', 'acceptedEvidence'],
  'paypal.order.created': ['checkpointId', 'orderId', 'amount', 'currency', 'environment'],
  'paypal.capture.requested': ['checkpointId', 'orderId', 'environment'],
  'paypal.capture.response_lost': ['checkpointId', 'orderId', 'outcome'],
  'paypal.webhook.received': ['checkpointId', 'eventId', 'captureId', 'duplicate', 'amount', 'currency'],
  'paypal.capture.reconciled': ['checkpointId', 'captureId', 'outcome', 'source'],
});

function requireId(value, label) {
  if (typeof value !== 'string' || !value || value.trim() !== value) {
    throw new Error(`${label} must be a nonempty string without surrounding whitespace`);
  }
}

function requireCents(value, label) {
  if (!Number.isSafeInteger(value) || value < 0) throw new Error(`${label} must be nonnegative safe integer cents`);
}

const fixtureOrderId = checkpointId => `SANDBOX-${checkpointId.toUpperCase()}`;

function copySeed(seed) {
  const copy = structuredClone(seed);
  if (!copy || !Array.isArray(copy.checkpoints)) throw new Error('Checkpoint seed is required');
  requireId(copy.currency, 'Currency');
  requireCents(copy.amount, 'Project cap');
  const ids = new Set();
  const orderIds = new Set();
  let total = 0;
  for (const cp of copy.checkpoints) {
    requireId(cp?.id, 'Checkpoint ID');
    if (ids.has(cp.id)) throw new Error('Checkpoint IDs must be unique');
    ids.add(cp.id);
    const orderId = fixtureOrderId(cp.id);
    if (orderIds.has(orderId)) throw new Error('Checkpoint IDs must produce unique fixture order IDs');
    orderIds.add(orderId);
    requireCents(cp.amount, 'Checkpoint amount');
    total += cp.amount;
    requireCents(total, 'Checkpoint total');
  }
  if (total > copy.amount) throw new Error('Checkpoint total exceeds the project cap');
  return copy;
}

function checkpoint(checkpoints, id) {
  if (typeof id !== 'string' || !Object.hasOwn(checkpoints, id)) throw new Error('Unknown checkpoint');
  return checkpoints[id];
}

function validateEnvelope(event) {
  if (!event || typeof event !== 'object' || Array.isArray(event) || typeof event.type !== 'string' || !Object.hasOwn(EVENT_FIELDS, event.type)) {
    throw new Error('Unsupported ledger event');
  }
  const allowed = ['seq', 'type', 'at', ...EVENT_FIELDS[event.type]];
  if (Object.keys(event).some(key => !allowed.includes(key))) throw new Error('Unsupported ledger event field');
  if (Object.hasOwn(event, 'seq') && (!Number.isSafeInteger(event.seq) || event.seq < 1)) throw new Error('Invalid event sequence');
  if (Object.hasOwn(event, 'at')) requireId(event.at, 'Event time');
}

function requireOrder(event, cp) {
  requireId(event.orderId, 'Order ID');
  if (event.orderId !== cp.orderId) throw new Error('Order identity conflict');
}

function requireAmount(event, cp, currency) {
  if (event.amount !== cp.amount || event.currency !== currency) throw new Error('Order amount or currency conflict');
}

export function createLedger(seed = FIXTURE) {
  const initialSeed = copySeed(seed);
  const events = [];
  const append = (type, data = {}) => {
    if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('Event data must be an object');
    const descriptors = Object.getOwnPropertyDescriptors(data);
    if (Object.values(descriptors).some(descriptor => !Object.hasOwn(descriptor, 'value'))) throw new Error('Event data must not contain accessors');
    if (['seq', 'type', 'at'].some(key => Object.hasOwn(descriptors, key))) throw new Error('Reserved event metadata');
    const payload = Object.fromEntries(Object.entries(descriptors).filter(([, descriptor]) => descriptor.enumerable).map(([key, descriptor]) => [key, descriptor.value]));
    const event = Object.freeze({ seq: events.length + 1, type, at: `T+${String(events.length + 1).padStart(3, '0')}`, ...payload });
    // Admission and replay use the same state machine. A refusal cannot alter
    // either the existing journal or the next logical sequence number.
    reduce([...events, event], initialSeed);
    events.push(event);
    return event;
  };
  const snapshot = () => reduce(events, initialSeed);
  const current = id => checkpoint(snapshot().checkpoints, id);
  return {
    get events() { return Object.freeze([...events]); },
    append,
    snapshot,
    approve: (checkpointId, evidence = initialSeed.checkpoints.find(cp => cp.id === checkpointId)?.evidence) => {
      current(checkpointId);
      if (typeof evidence !== 'string' || !evidence.trim()) throw new Error('Acceptance evidence is required for human approval');
      append('checkpoint.approved', { checkpointId, approver: 'human-reviewer', acceptedEvidence: evidence.trim() });
    },
    createOrder: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.order.created', { checkpointId, orderId: fixtureOrderId(checkpointId), amount: cp.amount, currency: initialSeed.currency, environment: 'sandbox' });
    },
    recordCaptureAttempt: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.capture.requested', { checkpointId, orderId: cp.orderId, environment: 'sandbox' });
    },
    recordLostCaptureResponse: (checkpointId) => {
      const cp = current(checkpointId);
      append('paypal.capture.response_lost', { checkpointId, orderId: cp.orderId, outcome: 'unknown' });
    },
    recordWebhook: (checkpointId, eventId, captureId) => {
      const cp = current(checkpointId);
      const duplicate = events.some(e => e.type === 'paypal.webhook.received' && e.eventId === eventId);
      append('paypal.webhook.received', { checkpointId, eventId, captureId, duplicate, amount: cp.amount, currency: initialSeed.currency });
    },
    reconcile: (checkpointId, captureId) => {
      current(checkpointId);
      append('paypal.capture.reconciled', { checkpointId, captureId, outcome: 'captured', source: 'sandbox-transaction-lookup' });
    }
  };
}

export function reduce(events, seed = FIXTURE) {
  if (!Array.isArray(events)) throw new Error('Ledger events must be an array');
  const initialSeed = copySeed(seed);
  const checkpoints = Object.fromEntries(initialSeed.checkpoints.map(cp => [cp.id, { ...cp, approved: false, orderId: null, captureStatus: 'not_started', captureId: null, counted: 0 }]));
  const orders = new Map();
  const webhooks = new Map();
  const captures = new Map();
  const checkpointCaptures = new Map();
  const bindCapture = event => {
    requireId(event.captureId, 'Capture ID');
    if ((captures.has(event.captureId) && captures.get(event.captureId) !== event.checkpointId)
      || (checkpointCaptures.has(event.checkpointId) && checkpointCaptures.get(event.checkpointId) !== event.captureId)) {
      throw new Error('Capture identity conflict');
    }
    captures.set(event.captureId, event.checkpointId);
    checkpointCaptures.set(event.checkpointId, event.captureId);
  };
  for (const event of events) {
    validateEnvelope(event);
    const cp = checkpoint(checkpoints, event.checkpointId);
    switch (event.type) {
      case 'checkpoint.approved':
        if (cp.approved) throw new Error('Checkpoint already approved');
        if (event.approver !== 'human-reviewer') throw new Error('Explicit fixture human approval required');
        if (typeof event.acceptedEvidence !== 'string' || !event.acceptedEvidence.trim()) throw new Error('Acceptance evidence is required for human approval');
        cp.approved = true;
        break;
      case 'paypal.order.created':
        if (!cp.approved) throw new Error('Human approval required before order creation');
        if (cp.orderId) throw new Error('Order already exists');
        requireId(event.orderId, 'Order ID');
        if (orders.has(event.orderId)) throw new Error('Order identity conflict');
        requireAmount(event, cp, initialSeed.currency);
        if (event.environment !== 'sandbox') throw new Error('Only the sandbox fixture environment is supported');
        orders.set(event.orderId, event.checkpointId);
        cp.orderId = event.orderId;
        cp.captureStatus = 'ready';
        break;
      case 'paypal.capture.requested':
        if (!cp.orderId) throw new Error('Approved PayPal order required before capture');
        if (cp.captureStatus === 'pending') throw new Error('Capture is already pending; do not retry before its outcome is recorded');
        if (cp.captureStatus === 'unknown') throw new Error('Capture is not safe to retry; reconcile first');
        if (cp.captureStatus === 'captured') throw new Error('Capture already completed; do not retry');
        requireOrder(event, cp);
        if (event.environment !== 'sandbox') throw new Error('Only the sandbox fixture environment is supported');
        cp.captureStatus = 'pending';
        cp.captureRequested = true;
        break;
      case 'paypal.capture.response_lost':
        if (cp.captureStatus !== 'pending') throw new Error('Only a pending capture can lose its response');
        requireOrder(event, cp);
        if (event.outcome !== 'unknown') throw new Error('A lost capture response has an unknown outcome');
        cp.captureStatus = 'unknown';
        break;
      case 'paypal.webhook.received': {
        if (!cp.orderId) throw new Error('Order required before webhook');
        requireId(event.eventId, 'Webhook event ID');
        requireId(event.captureId, 'Capture ID');
        const prior = webhooks.get(event.eventId);
        if (prior && (prior.checkpointId !== event.checkpointId || prior.captureId !== event.captureId
          || prior.amount !== event.amount || prior.currency !== event.currency)) throw new Error('Webhook event identity conflict');
        requireAmount(event, cp, initialSeed.currency);
        if (event.duplicate !== Boolean(prior)) throw new Error('Webhook duplicate marker conflicts with event history');
        bindCapture(event);
        webhooks.set(event.eventId, event);
        // Receipt identity is retained during an unknown outcome, but receiving
        // a webhook does not replace the fixture's explicit reconciliation.
        if (!prior && cp.captureStatus !== 'captured' && cp.captureStatus !== 'unknown') {
          cp.captureStatus = 'captured'; cp.captureId = event.captureId; cp.counted = cp.amount;
        }
        break;
      }
      case 'paypal.capture.reconciled':
        if (cp.captureStatus !== 'unknown') throw new Error('Only an unknown capture can be reconciled');
        if (event.outcome !== 'captured' || event.source !== 'sandbox-transaction-lookup') throw new Error('Sandbox lookup evidence required for reconciliation');
        bindCapture(event);
        cp.captureStatus = 'captured'; cp.captureId = event.captureId; cp.counted = cp.amount;
        break;
    }
  }
  const total = initialSeed.checkpoints.reduce((sum, cp) => sum + cp.amount, 0);
  const approved = Object.values(checkpoints).filter(cp => cp.approved).length;
  const captured = Object.values(checkpoints).reduce((sum, cp) => sum + cp.counted, 0);
  return { checkpoints, total, approved, captured, remaining: total - captured };
}

export function replayFixture() {
  const ledger = createLedger();
  // Gate all payment action on explicit human acceptance; the first checkpoint
  // demonstrates a lost response, duplicated webhook, then read-only reconcile.
  ledger.approve('journey');
  ledger.createOrder('journey');
  ledger.recordCaptureAttempt('journey');
  ledger.recordLostCaptureResponse('journey');
  ledger.recordWebhook('journey', 'WH-EVT-FIXTURE-001', 'CAP-FIXTURE-001');
  ledger.recordWebhook('journey', 'WH-EVT-FIXTURE-001', 'CAP-FIXTURE-001');
  ledger.reconcile('journey', 'CAP-FIXTURE-001');
  return ledger;
}

import { FIXTURE, SPEC_VERSION, reduce } from './ledger.mjs';

export const FIXTURE_RECORD_FILENAME = 'scopesignal-fixture-record-v1.json';

export function createFixtureRecord(events) {
  const recordedEvents = structuredClone(events);
  const state = reduce(recordedEvents);
  return {
    schema: 'scopesignal.fixture-record',
    version: 1,
    ledgerSpecVersion: SPEC_VERSION,
    fixtureOnly: true,
    paymentEvidence: false,
    notice: 'Synthetic ScopeSignal fixture. This is not a payment receipt or evidence of a real transaction.',
    fixture: { id: FIXTURE.id, label: FIXTURE.label, currency: FIXTURE.currency, amount: FIXTURE.amount },
    summary: { total: state.total, approved: state.approved, captured: state.captured, remaining: state.remaining },
    checkpoints: FIXTURE.checkpoints.map(checkpoint => {
      const current = state.checkpoints[checkpoint.id];
      const acceptance = recordedEvents.find(event => event.type === 'checkpoint.approved' && event.checkpointId === checkpoint.id);
      return {
        id: checkpoint.id,
        title: checkpoint.title,
        amount: checkpoint.amount,
        approval: acceptance ? { source: 'checkpoint.approved', eventSequence: acceptance.seq, approver: acceptance.approver, acceptedEvidence: acceptance.acceptedEvidence } : null,
        capture: { status: current.captureStatus, orderId: current.orderId, captureId: current.captureId, counted: current.counted },
      };
    }),
    events: recordedEvents,
  };
}

export function serializeFixtureRecord(events) {
  return JSON.stringify(createFixtureRecord(events), null, 2) + '\n';
}

